function head(title,back=false){return `<header class="app-head">${back?`<button class="iconbtn" data-action="back" aria-label="뒤로">${icon('back')}</button><b>${title}</b>`:`<div class="wordmark animated-wordmark" role="img" aria-label="BUSAN DROP" style="--wordmark-phase:-${Date.now()%12000}ms"><span class="wordmark-original" aria-hidden="true">BUSAN DROP<em>↘</em></span><span class="wordmark-fill" aria-hidden="true">BUSAN DROP<em>↘</em></span></div>`}<div class="head-actions">${!back?`<button class="iconbtn" data-nav="browse" aria-label="검색">${icon('search')}</button>`:''}<button class="iconbtn" data-nav="profile" aria-label="마이">${icon('user')}</button></div></header>`}const productCategories=['전체','여성의류','남성의류','키즈·베이비','신발·가방','패션잡화','스킨케어','메이크업','바디·헤어','향수'];
