function chips(){const isBrand=state.screen==='brands',options=isBrand?['전체',...brands.map(b=>b.name),'패션','뷰티']:productCategories;return `<div class="chips ${isBrand?'':'product-category-chips'}" aria-label="${isBrand?'브랜드':'상품 카테고리'}">${options.map(c=>`<button class="chip ${state.filter===c?'active':''}" data-filter="${c}" aria-pressed="${state.filter===c}">${isBrand?c:`<span class="category-picture">${categoryArt(c)}</span><span class="category-name">${c}</span>`}</button>`).join('')}</div>`}function search(ph){return `<label class="search">${icon('search')}<input id="search" type="search" placeholder="${ph}" aria-label="${ph}" value="${esc(state.query)}"></label>`}function saveBtn(id){return `<button class="save ${state.saved.has(id)?'saved':''}" aria-label="${state.saved.has(id)?'저장 해제':'혜택 저장'}" aria-pressed="${state.saved.has(id)}" data-save="${id}">${icon('heart')}</button>`}
function thumbnailFor(d){const key=d.thumbnailKey||`deal-${d.id}`;const item=window.BUSAN_THUMBNAILS?.[key];return item&&/^assets\/products\/[a-z0-9-]+\/[a-f0-9]+\.png$/.test(item.src)?item:null}
function thumbnailImage(d){const item=thumbnailFor(d);return item?`<img class="managed-thumbnail" src="${esc(item.src)}" alt="${esc(item.alt)}" loading="lazy">`:''}
function card(d){return d.product?productCard(d):realCard(d)}
const product={id:7,thumbnailKey:'nivea-repair-care',brand:1,product:true,title:'니베아 리페어 앤 케어 크림 400ml',tag:'BLACK FRIDAY',cat:'뷰티',category:'바디·헤어',discount:44,original:22500,price:12500,desc:'펌프기획 증정 · 건조한 계절의 보습 루틴',url:'https://www.oliveyoung.co.kr/store/goods/getGoodsDetail.do?goodsNo=A000000231772&dispCatNo=500000100019BDJ',start:'2026-11-01T00:00:00+09:00',end:'2026-11-08T00:00:00+09:00'};
deals.unshift(product);
const money=n=>n.toLocaleString('ko-KR');
function eventStatus(now=Date.now()){return now< Date.parse(product.start)?'예정':now>=Date.parse(product.end)?'종료':'진행 중'}
function clockText(now=Date.now()){if(eventStatus(now)==='종료')return '행사 종료';if(eventStatus(now)==='예정')return '11.01 시작 예정';let t=Math.max(0,Math.floor((Date.parse(product.end)-now)/1000));return `${Math.floor(t/86400)}일 ${String(Math.floor(t/3600)%24).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}
function productArt(detail=false){return `<div class="product-art ${detail?'large':''}"><span class="product-kicker">OLIVE YOUNG × NIVEA</span><img src="${esc(thumbnailFor(product)?.src||'assets/nivea-black-friday.png')}" alt="${esc(thumbnailFor(product)?.alt||'니베아 리페어 앤 케어 크림 제품 연출 이미지')}" ${detail?'':'loading="lazy"'}><span class="product-sticker">44%<small>OFF</small></span></div>`}
function priceBlock(){return `<div class="price-block"><del>정상가 22,500원</del><div><strong class="product-rate">44%</strong><b>12,500<small>원~</small></b></div><span>10,000원 절약 · 최저 옵션</span></div>`}
function urgency(){return `<div class="event-clock"><span>● 올영 블프 · <span data-event-status>${eventStatus()}</span></span><strong data-event-clock>${clockText()}</strong><small>행사 기간 2026.11.01 – 11.07 · 한국 시간 기준</small></div>`}
function cardPrices(d){return `<div class="card-prices"><del>${money(d.original)}원</del><div><strong>${d.discount}%</strong><b>${money(d.price)}<small>원${d.product?'~':''}</small></b></div></div>`}
function productCard(d){return `<article class="deal-card product-card"><div class="product-cover"><button class="product-image-button" data-deal="${d.id}" aria-label="${d.title} 상세 보기">${productArt()}</button>${saveBtn(d.id)}</div><div class="deal-content" role="button" tabindex="0" data-deal="${d.id}"><div class="deal-meta"><span class="badge">${brands[d.brand].name}</span></div><h3>${d.title}</h3>${cardPrices(d)}</div></article>`}
