function productDetail(){return head('상품 상세',true)+productArt(true)+`<div class="pad product-detail"><div class="deal-meta"><span class="badge">올리브영</span><span>니베아 / 바디케어</span></div><h2 class="page-heading">니베아 리페어 앤 케어 크림 400ml</h2><p class="product-sub">펌프 증정</p>${priceBlock()}${detailStoreButton(1)}<div class="detail-row"><span>판매처 / 제조 브랜드</span><strong>올리브영 / 니베아</strong></div><div class="detail-row"><span>블랙프라이데이 기간</span><strong>2026.11.01 – 11.07</strong></div><p class="notice">11.02 확인 · 옵션별 가격 상이. 행사 종료와 상품 할인 종료는 다를 수 있습니다. 연출 이미지.</p><div class="product-sources"><a href="${product.url}" target="_blank" rel="noopener noreferrer">가격 출처 ↗</a><a href="https://corp.oliveyoung.com/ko/newsroom/editorial/338" target="_blank" rel="noopener noreferrer">행사 출처 ↗</a></div><div class="section-title"><h3>올리브영 더 둘러보기</h3><button class="textbtn" data-brand="1">브랜드 보기 ↗</button></div>${deals.filter(d=>d.brand===1&&!d.product).map(card).join('')}</div>`}
const banners=[0,1,2,3,'busan'];

function normalizeShoppingTypes(value){const allowed=['뷰티','패션','로컬/팝업'];const chosen=allowed.filter(t=>(Array.isArray(value)?value:[value]).includes(t));return chosen.length?chosen:allowed}
function likesShopping(type){return state.shoppingTypes.includes(type)}
function validVisitDate(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!isNaN(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value}
function hasVisit(){return validVisitDate(state.visitStart)&&validVisitDate(state.visitEnd)&&state.visitStart<=state.visitEnd}
function matchesVisit(event){return !hasVisit()||(event.verified!==false&&!!event.start&&!!event.end&&event.start<=state.visitEnd&&event.end>=state.visitStart)}
function visitOrder(a,b){if(!hasVisit())return 0;const offset=e=>e.start?Math.max(0,Date.parse(e.start)-Date.parse(state.visitStart)):Infinity;return offset(a)-offset(b)}
function visitLabel(event){if(!hasVisit())return saleStatus(event).label;const days=Math.round((Date.parse(event.start)-Date.parse(state.visitStart))/86400000);return days<=0?'방문일부터 진행 중':'방문일 +'+days+'일 시작'}
function orderedBrands(){return brands.map((b,i)=>({...b,i})).sort((a,b)=>visitOrder(a,b)||(Number(likesShopping(b.cat))-Number(likesShopping(a.cat)))||a.i-b.i)}
function refreshCampaigns(){const list=orderedBrands().filter(matchesVisit).map(b=>b.i);if(likesShopping('로컬/팝업')&&state.shoppingTypes.length<3)list.unshift('busan');else list.push('busan');banners.splice(0,banners.length,...list);state.banner=Math.min(state.banner,banners.length-1)}

function tripDock(){return `<button class="visit-dock" data-trip-edit="true" aria-label="방문 날짜와 쇼핑 타입 수정"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-13 5h3m3 0h3"/></svg><span><strong>방문 설정</strong><small>${hasVisit()?visitDateText():'날짜 선택'} · ${state.shoppingTypes.length===3?'모든 취향':state.shoppingTypes.join(' · ')}</small></span><b aria-hidden="true">↗</b></button>`}
function maybeShowTripPrompt(){if(state.screen!=='home'||state.tripPromptSeen)return;state.tripPromptSeen=true;persist();openTripSettings()}
function openTripSettings(){if(state.screen!=='home')return;$('#modal').innerHTML=localizeHtml(`<div class="overlay"><section class="sheet trip-sheet" role="dialog" aria-modal="true" aria-label="방문 설정">${tripPreferences()}<button class="secondary" data-action="close">닫기</button></section></div>`);bindTripForm($('#modal #tripForm'));$('#modal input')?.focus()}

function shoppingTypeArt(type){const drawings={
 '전체':'<path d="M13 18h38l-3 33H16Z" fill="#FFD628"/><path d="M23 20v-4a9 9 0 0 1 18 0v4" fill="none"/><path d="m43 7 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#fff"/><path d="m25 35 5 5 10-12" fill="none"/>',
 '뷰티':'<path d="M17 32h16v21H17Z" fill="#FFD628"/><path d="M20 32V20l10-6v18Z" fill="#fff"/><path d="M39 29h13v24H39Z" fill="#fff"/><path d="M41 23h9v6h-9Z" fill="#FFD628"/><path d="m45 7 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#FFD628"/>',
 '패션':'<path d="m23 13-14 9 7 14 8-4v21h24V32l8 4 7-14-15-9c-3 9-16 9-20 0Z" transform="translate(-4 0)" fill="#FFD628"/><path d="m24 13 8 12 8-12M32 25v28" fill="none"/><circle cx="37" cy="32" r="1.4" fill="currentColor" stroke="none"/>',
 '로컬/팝업':'<path d="M13 29h38v24H13Z" fill="#fff"/><path d="M10 29h44l-5-15H15Z" fill="#FFD628"/><path d="M21 15 19 29m13-14v14m11-14 2 14M11 29q5 8 10 0 5 8 11 0 6 8 11 0 5 8 10 0" fill="none"/><path d="M28 40h11v13H28Z" fill="#FFD628"/><path d="M45 7v6m-3-3h6" fill="none"/>'
 };return `<svg class="shopping-type-art" viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[type]||drawings['전체']}</svg>`}

function visitDateText(){const label=d=>Number(d.slice(5,7))+'월 '+Number(d.slice(8,10))+'일';return hasVisit()?label(state.visitStart)+(state.visitEnd!==state.visitStart?' – '+label(state.visitEnd):''):'미정'}
function tripPreferences(onboarding=false){return `<section class="trip-preferences"><form id="tripForm" data-onboarding="${onboarding}"><h3>${state.tripConfigured||hasVisit()?'방문 날짜':'언제 부산 오세요?'}</h3><p>방문 기간에 열리는 행사를 모아드려요.</p><div class="trip-dates"><label>도착일<input type="date" name="visitStart" aria-label="부산 도착일" value="${hasVisit()?state.visitStart:''}"></label><span aria-hidden="true">–</span><label>마지막 날<input type="date" name="visitEnd" aria-label="부산 방문 마지막 날" value="${hasVisit()?state.visitEnd:''}"></label></div><fieldset><legend>어떤 쇼핑을 좋아하세요? <small class="multi-choice-hint">복수 선택 가능</small></legend><div class="trip-types">${['전체','뷰티','패션','로컬/팝업'].map(t=>`<label><input type="checkbox" name="shoppingType" value="${t}" ${(t==='전체'?state.shoppingTypes.length===3:likesShopping(t))?'checked':''}><span>${shoppingTypeArt(t)}<b>${t==='전체'?'모두':t}</b></span></label>`).join('')}</div></fieldset><p class="form-error" id="tripError" role="alert"></p><button class="primary" type="submit">${onboarding?'내 취향으로 시작하기':'내 일정에 맞춰 보기'} ↗</button>${!onboarding&&hasVisit()?'<button class="guest" type="button" data-trip-clear="true">방문 날짜 지우기 · 전체 일정 보기</button>':''}</form></section>`}

function koreaDay(now=Date.now()){return new Date(now+9*3600000).toISOString().slice(0,10)}
function saleStatus(b,now=Date.now()){
 if(b.verified===false||!b.start||!b.end)return {label:'일정 확인 중',copy:'공식 발표 후 D-day를 안내해요',phase:'unknown'};
 const today=koreaDay(now),days=(a,c)=>Math.round((Date.parse(a+'T00:00:00+09:00')-Date.parse(c+'T00:00:00+09:00'))/86400000);
 if(today<b.start){const n=days(b.start,today);return {label:'D-'+n,copy:'행사 시작까지' ,phase:'upcoming'}}
 if(today>b.end)return {label:'행사 종료',copy:'다음 소식은 공식몰에서 확인해주세요',phase:'ended'};
 const n=days(b.end,today);return {label:n===0?'오늘 마감':'종료 D-'+n,copy:'현재 진행 중 · 행사 종료까지',phase:'active'};
}
function salePanel(b,i){const t=saleStatus(b);return `<section class="sale-panel"><div class="sale-panel-top"><span class="verification ${b.verified?'confirmed':''}">${b.verified?'확정':'미확정'}</span><strong data-sale-timer="${i}">${t.label}</strong></div><h3>${b.sale}</h3><p>${b.verified?'2026.'+b.period:'행사 기간 미확정'}</p>${!b.verified?`<p class="reported-period">제보 일정 ${b.reported} · 미검증</p>`:''}<a href="${b.source}" target="_blank" rel="noopener noreferrer">${b.verified?'공식 일정 출처':'확인한 공식 채널'} ↗</a></section>`}
function catalogPlaceholder(){return '<div class="catalog-placeholder"><span>상품 이미지 준비 중</span></div>'}
function realCard(d){const image=thumbnailImage(d);return `<article class="deal-card verified-deal"><button class="real-art" data-deal="${d.id}" aria-label="${d.title} 상세 보기">${image||catalogPlaceholder()}${image?`<em>${d.discount}%<small>OFF</small></em>`:''}</button><div class="real-card-save">${saveBtn(d.id)}</div><div class="deal-content" role="button" tabindex="0" data-deal="${d.id}"><div class="deal-meta"><span class="badge">${brands[d.brand].name}</span></div><h3>${d.title}</h3>${cardPrices(d)}</div></article>`}
function realDetail(){const d=deals.find(d=>d.id===state.deal);if(!d)return head('상품 상세',true)+empty('등록되지 않은 상품이에요','현재 상품 목록을 확인해주세요.');const b=brands[d.brand];return head('상품 상세',true)+`<div class="pad"><h2 class="page-heading">${d.title}</h2><div class="real-price"><del>정상가 ${money(d.original)}원</del><strong>${d.discount}% · ${money(d.price)}원</strong><span>${money(d.original-d.price)}원 절약</span></div>${detailStoreButton(d.brand)}${salePanel(b,d.brand)}<p class="notice">11.02 확인 · 가격·재고 변동 가능. 상품 사진 미등록.</p><button class="secondary" data-brand="${d.brand}">${b.name} 브랜드관 더 보기 ↗</button></div>`}
const places=window.BUSAN_CONTENT.places;
function placeCard(p){const t=p.end?{label:visitLabel(p)}:{label:'로컬 스폿',phase:'local'};return `<button class="place-card ${p.type==='팝업 스토어'?'popup-card':''}" data-place="${p.id}"><span class="place-card-top"><span>${p.area} / ${p.type}</span><span class="place-status">${t.label}</span></span><strong>${p.name}</strong><span class="place-card-bottom">${p.period?p.period:p.area}<b>둘러보기 ↗</b></span></button>`}
function busan(){const list=places.filter(p=>(!p.start||matchesVisit(p))&&(state.localFilter==='전체'||p.type===state.localFilter)&&(state.area==='전체'||p.area===state.area)).sort(visitOrder);return head()+`<div class="pad"><section class="busan-heading"><h2>부산</h2><p>부산의 취향을 담은 로컬 브랜드부터 여행 중 들를 팝업까지, 한곳에서 만나보세요.</p><div class="busan-scene" role="img" aria-label="광안대교와 부산의 바다, 갈매기를 담은 모션그래픽">${busanBannerArt()}${busanBannerSea()}</div></section>${hasVisit()?'<p class="notice">방문 기간 내 팝업과 상설 로컬 스폿을 표시해요.</p>':''}<div class="chips">${['전체','로컬 브랜드','팝업 스토어'].map(c=>`<button class="chip ${state.localFilter===c?'active':''}" data-local-filter="${c}">${c}</button>`).join('')}</div><div class="area-filters" aria-label="부산 지역 필터">${['전체','전포','영도','센텀'].map(a=>`<button class="${state.area===a?'active':''}" data-area="${a}">${a}</button>`).join('')}</div><div class="section-title"><h3>${state.localFilter==='전체'?'부산 취향 지도':state.localFilter}</h3><span class="small">${list.length}곳</span></div><div class="home-local-list busan-local-list">${list.map(homePlaceRow).join('')||'<div class="local-empty"><h3>이 지역의 콘텐츠를 준비 중이에요.</h3><p>다른 지역이나 전체 필터를 선택해보세요.</p></div>'}</div><p class="notice">방문 전 운영시간을 확인해주세요.</p></div>`}
function placePage(){const p=places.find(p=>p.id===state.place);return head(p.name,true)+`<div class="pad"><div class="local-detail-hero"><span class="local-detail-label">${p.area} · ${p.type}</span><h2>${p.name}</h2></div><div class="detail-row"><span>위치</span><strong>${p.address}</strong></div><div class="detail-row"><span>운영 형태</span><strong>${p.type}</strong></div>${p.period?`<div class="detail-row"><span>행사 기간</span><strong>2026.${p.period}</strong></div><div class="local-count">${saleStatus(p).label} · 한국 날짜 기준</div>`:''}<p class="notice">방문 전 운영시간 확인</p><div class="product-sources"><a href="${p.source}" target="_blank" rel="noopener noreferrer">출처 ↗</a></div><a class="primary official-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.type==='팝업 스토어'?'공식 팝업 안내':'브랜드 공식 채널'} 보기 ↗</a><button class="secondary local-return" data-nav="busan">부산 목록 ↗</button></div>`}
specs.busan=['부산의 취향을 발견하는 테마관','전국 브랜드관과 구분한 부산 로컬·팝업 큐레이션입니다.',['콘텐츠 분류|로컬 브랜드 / 팝업 스토어|공식 출처 확인 정보와 현장 방문 연결','지역 필터|전포 / 영도 / 센텀|종류와 지역을 조합해 탐색','팝업 일정|한국 날짜 기준 D-day|기간 종료 후 종료 상태 안내','공식 채널|각 콘텐츠 상세|주소·기간·출처 확인 후 외부 이동']];
specs.place=['부산 스폿 상세','로컬 브랜드와 팝업의 위치·기간·공식 채널을 안내합니다.',['방문 정보|위치 / 유형 / 행사 기간|상설 스폿과 기간 한정 행사를 구분','정보 출처|공식 채널 링크|방문 전 최신 운영 상태 확인']];
specs.home=['브랜드 행사부터 부산의 취향까지','상품 추천 배너를 브랜드 행사 캘린더로 개편했습니다.',['행사 배너|브랜드별 기간과 D-day|확정 일정만 날짜 기준으로 계산','브랜드관|탑텐 / 올리브영 / 유니클로 / 자라|브랜드 상품과 공식 상품군 탐색','부산 진입|브랜드 줄 첫 아이콘 + 하단 부산 탭|파도 모션의 BUSAN 아이콘으로 로컬 탐색']];
specs.brand=['브랜드 행사와 상품','공식 일정과 미확정 소식을 구분해 제공합니다.',['행사 확인|기간 / 검증 상태 / 출처|미확정 행사 D-day 미표시','상품 탐색|확인 상품 / 공식 상품군|실제 기획전 가격 또는 공식 카테고리 연결']];
specs.detail=['상품 정보와 공식몰 연결','기획전에서 확인한 가격·기간을 안내합니다.',['가격 비교|정상가 / 판매가 / 절약액|확인 시점과 옵션 차이 안내','공식 구매|상품 URL|공식몰에서 최종 가격과 재고 확인']];

const bridge=`<svg class="bridge" viewBox="0 0 346 60" aria-hidden="true"><path d="M0 52h346M62 52V8m220 44V8M0 45Q62 48 62 10q110 65 220 0 0 38 64 35M14 47v5m25-13v13m48-25v25m24-14v14m24-6v6m24-2v2m24-2v2m24-7v7m24-14v14m24-25v25m50-12v12m23-6v6"/></svg>`;
function intro(){return `<section class="intro-screen"><div class="intro-top"><span>BUSAN SHOPPING PASS</span><button class="skip" data-nav="language">건너뛰기 ↗</button></div><h2>부산 가기 전,<br><em>혜택부터</em><br>챙겨요.</h2><div class="intro-art"><div class="intro-tag t1"><span class="sticker-face"><small>DESTINATION / 01</small>BUSAN ↗</span></div><div class="intro-tag t2"><span class="sticker-face">BLACK FRIDAY</span></div><div class="intro-tag t3"><span class="sticker-face">▥ &nbsp; SAVE YOUR DROP</span></div></div><button class="primary" data-nav="language">혜택 둘러보기 ${icon('arrow')}</button><button class="guest" data-language-next="signup">나만의 패스 만들기</button></section>`}
function busanBrandIcon(){return `<span class="brand-logo busan-brand-icon" aria-hidden="true"><span class="busan-wordmark">BUSAN</span><svg class="busan-wave busan-wave-back" viewBox="0 0 200 100" preserveAspectRatio="none"><path d="M0 22 Q25 2 50 22 T100 22 T150 22 T200 22 T250 22 T300 22 V140 H0Z"/></svg><svg class="busan-wave busan-wave-front" viewBox="0 0 200 100" preserveAspectRatio="none"><path d="M0 24 Q25 44 50 24 T100 24 T150 24 T200 24 T250 24 T300 24 V140 H0Z"/></svg></span>`}
function busanBrandShortcut(){return `<button class="brand-mini busan-brand-shortcut" data-nav="busan" aria-label="부산 로컬 브랜드와 팝업 둘러보기">${busanBrandIcon()}<span>부산</span></button>`}
function busanBannerArt(){return `<svg class="busan-banner-art" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><circle class="busan-sun" cx="326" cy="103" r="45" fill="currentColor" opacity=".13"/><g class="busan-city" fill="currentColor"><path opacity=".18" d="M224 207V157H239V207M243 207V131H258V207M264 207V146H280V207M289 207V118L302 108 315 118V207M321 207V142H335V207M341 207V164H360V207"/><path opacity=".35" d="M232 207V180H254V207M261 207V165H275V207M280 207V152H294V207M303 207V173H322V207M329 207V156H343V207"/></g><g class="busan-bridge" fill="none" stroke="currentColor" stroke-linecap="round"><path d="M19 224Q194 211 382 224" stroke-width="5"/><path d="M130 225V155M285 221V143" stroke-width="5"/><path d="M25 221Q91 220 130 158Q205 253 285 146Q328 214 381 223" stroke-width="2"/><path d="M68 214V222M91 198V220M111 179V220M151 181V218M173 202V218M196 214V217M218 212V218M241 193V219M263 168V220M308 175V221M332 202V222M354 215V223" stroke-width="1" opacity=".6"/></g><g class="busan-gulls" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M283 49Q291 41 299 49Q307 41 315 49M333 68Q339 62 345 68Q351 62 357 68"/></g><g class="busan-camellia" transform="translate(357 121)"><g fill="currentColor"><ellipse cy="-9" rx="7" ry="10"/><ellipse cy="-9" rx="7" ry="10" transform="rotate(72)"/><ellipse cy="-9" rx="7" ry="10" transform="rotate(144)"/><ellipse cy="-9" rx="7" ry="10" transform="rotate(216)"/><ellipse cy="-9" rx="7" ry="10" transform="rotate(288)"/></g><circle r="4" fill="#111"/></g><g class="busan-sea"><path class="busan-sea-back" d="M-100 259Q-50 239 0 259T100 259T200 259T300 259T400 259T500 259V330H-100Z" fill="currentColor" opacity=".12"/><path class="busan-sea-front" d="M-100 278Q-50 260 0 278T100 278T200 278T300 278T400 278T500 278V330H-100Z" fill="currentColor" opacity=".24"/></g></svg>`}
function busanBannerSea(){return `<svg class="busan-banner-full-sea" viewBox="0 0 600 80" preserveAspectRatio="none" aria-hidden="true"><path class="busan-sea-back" d="M-200 26Q-150 6-100 26T0 26T100 26T200 26T300 26T400 26T500 26T600 26T700 26T800 26V100H-200Z" fill="currentColor" opacity=".12"/><path class="busan-sea-front" d="M-200 49Q-150 31-100 49T0 49T100 49T200 49T300 49T400 49T500 49T600 49T700 49T800 49V100H-200Z" fill="currentColor" opacity=".24"/></svg>`}
function campaignBanner(){const i=banners[state.banner]??0,isBusan=i==='busan',b=isBusan?{name:'BUSAN',sale:'부산의 취향을<br>발견하는 순간.'}:brands[i];return `<div class="campaign-stage"><section class="hero calendar-hero illustrated-campaign ${isBusan?'busan-destination':['topten','olive','uniqlo','zara'][i]}-campaign" id="hero" aria-label="${b.name} 행사 배너">${isBusan?busanBannerArt()+busanBannerSea():`<img class="campaign-illustration" src="assets/banners/${['topten-shopping-v1.png','oliveyoung-shopping.png','uniqlo-shopping-v1.png','zara-shopping-v1.png'][i]}" alt="${b.name} 쇼핑 일러스트">`}<div class="campaign-copy"><span class="campaign-brand-tag">${b.name}</span><h2>${b.sale}</h2><div class="campaign-meta">${isBusan?'<span class="campaign-date">로컬 브랜드 · 팝업 · 바다의 도시</span>':`<span class="campaign-date">${b.verified?b.period:'일정 미확정'}</span>${b.verified?`<strong class="campaign-timer" data-sale-timer="${i}">${visitLabel(b)}</strong>`:''}`}</div></div><div class="campaign-actions">${isBusan?'<button class="hero-cta" data-nav="busan">부산 둘러보기 ↗</button>':`<button class="hero-cta" data-brand="${i}">상품 보기 ↗</button><button class="hero-store" data-stores="${i}">매장 찾기 <span aria-hidden="true">⌖</span></button>`}</div></section></div><div class="campaign-pagination" aria-label="행사 배너 선택"><div class="dots">${banners.map((key,n)=>`<button class="${n===state.banner?'on':''}" data-banner="${n}" aria-label="${key==='busan'?'부산':brands[key].name} 행사 배너" aria-pressed="${n===state.banner}"></button>`).join('')}</div></div>`}
function homePlaceRow(p){const status=p.end?visitLabel(p):'로컬 스폿';return `<button class="home-place-row" data-place="${p.id}"><span class="home-place-main"><small>${p.type}</small><strong>${p.name}</strong><span class="home-place-meta">${p.area}${p.period?' · '+p.period:''}</span></span><span class="home-place-side"><span class="home-place-status">${status}</span><span class="home-place-arrow" aria-hidden="true">↗</span></span></button>`}
function home(){refreshCampaigns();return head()+campaignBanner()+`<div class="pad"><div class="section-title"><h3>브랜드별 할인 정보</h3><button class="textbtn" data-nav="brands">브랜드관 ↗</button></div><div class="brand-strip">${likesShopping('로컬/팝업')&&state.shoppingTypes.length<3?busanBrandShortcut():''}${orderedBrands().map(b=>`<button class="brand-mini" data-brand="${b.i}"><span class="brand-logo">${b.logo}</span>${b.name}</button>`).join('')}${!likesShopping('로컬/팝업')||state.shoppingTypes.length===3?busanBrandShortcut():''}</div>${likesShopping('로컬/팝업')&&state.shoppingTypes.length<3?`<div class="section-title"><h3>로컬 / 팝업</h3><button class="textbtn" data-nav="busan">전체 보기 ↗</button></div><div class="home-local-list">${places.filter(p=>!p.start||matchesVisit(p)).sort(visitOrder).map(homePlaceRow).join('')}</div>`:''}<div class="section-title"><h3>블프 할인 상품</h3><button class="textbtn" data-nav="browse">전체 보기 ↗</button></div>${chips()}<div id="results" class="product-grid">${filtered().slice(0,3).map(card).join('')||empty('상품을 준비하고 있어요','브랜드관에서 공식 상품군을 먼저 둘러보세요.','brands')}</div></div>`}
function filtered(){let list=deals.filter(d=>matchesVisit(brands[d.brand])&&(state.filter==='전체'||brands[d.brand].name===state.filter||d.cat===state.filter||d.category===state.filter)&&(!state.query||(`${d.title} ${brands[d.brand].name} ${d.cat} ${d.category||''}`).toLowerCase().includes(state.query.toLowerCase())));return state.sort==='discount'?list.sort((a,b)=>b.discount-a.discount):list.sort((a,b)=>visitOrder(brands[a.brand],brands[b.brand])||Number(likesShopping(b.cat))-Number(likesShopping(a.cat)))}function empty(title,copy,nav='browse'){return `<div class="empty"><span class="empty-symbol">${icon('heart')}</span><h3>${title}</h3><p>${copy}</p><button class="primary" data-nav="${nav}">상품 둘러보기 ${icon('arrow')}</button></div>`}
function browse(){return head()+`<div class="pad"><h2 class="page-heading">상품</h2>${search('브랜드나 혜택을 검색하세요')}${chips()}<div class="sort"><span id="resultCount">${filtered().length}개의 혜택</span><select id="sort" aria-label="혜택 정렬"><option value="recommended" ${state.sort==='recommended'?'selected':''}>추천순</option><option value="discount" ${state.sort==='discount'?'selected':''}>할인율순</option></select></div><div id="results" class="product-grid">${filtered().map(card).join('')||empty('등록된 상품이 없어요','브랜드관에서 공식 상품군을 둘러보세요.','brands')}</div></div>`}
function brandPage(){const b=brands[state.brand],items=deals.filter(d=>d.brand===state.brand);return head(b.name+' 브랜드관',true)+`<div class="pad"><section class="brand-heading"><h2>${b.name}</h2></section>${salePanel(b,state.brand)}<div class="section-title"><h3>${items.length?'상품':'상품군'}</h3><span class="small">${items.length?items.length+'개':'가격은 공식몰에서'}</span></div><div class="product-grid">${items.map(card).join('')}</div>${b.categories.map(c=>`<a class="catalog-link" href="${c.url}" target="_blank" rel="noopener noreferrer"><span><strong>${c.name}</strong></span><b>↗</b></a>`).join('')}<p class="notice">${items.length?'11.02 확인 · 가격·재고 변동 가능':'행사 일정·상품 미확정'}</p><a class="secondary official-link" href="${b.url}" target="_blank" rel="noopener noreferrer">${b.name} 공식몰 ↗</a></div>`}
function brandList(){return head()+`<div class="pad"><h2 class="page-heading">브랜드</h2>${search('브랜드 이름으로 검색')}${chips()}<div id="brandResults">${brandRows()}</div></div>`}function brandRows(){let list=brands.map((b,i)=>({...b,i})).filter(b=>(state.filter==='전체'||b.name===state.filter||b.cat===state.filter)&&(`${b.name} ${b.logo}`).toLowerCase().includes(state.query.toLowerCase()));const showBusan=(state.filter==='전체')&&(!state.query||'부산 busan 로컬 팝업'.includes(state.query.toLowerCase()));return (showBusan?`<button class="brand-row busan-brand-row" data-nav="busan" aria-label="부산 로컬 브랜드와 팝업 둘러보기">${busanBrandIcon()}<span class="busan-row-copy"><strong>부산</strong><span>로컬 브랜드 · 팝업 둘러보기</span></span><span aria-hidden="true">↗</span></button>`:'')+list.map(b=>`<div class="brand-row"><div class="brand-logo">${b.logo}</div><div><h3>${b.name}</h3><p>${b.verified?b.period+' · '+saleStatus(b).label:'공식 일정 확인 전'}</p></div><button class="iconbtn go" data-brand="${b.i}" aria-label="${b.name} 혜택 보기">${icon('arrow')}</button></div>`).join('')||'<p class="notice">검색 결과가 없어요. 검색어나 필터를 바꿔주세요.</p>'}
function saved(){let list=deals.filter(d=>state.saved.has(d.id));return head()+`<div class="pad"><h2 class="page-heading">마음에 든 혜택 ${list.length}<span style="color:var(--accent)">.</span></h2>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:empty('아직 비어 있는 패스','혜택 카드의 하트를 누르면<br>이곳에 모아둘 수 있어요.')}</div>`}
function detail(){return state.deal===7?productDetail():realDetail()}
function signup(){const login=state.authMode==='login';return head('패스 만들기/로그인',true)+`<div class="form"><div class="auth-tabs" role="group" aria-label="패스 만들기 또는 로그인"><button class="${!login?'active':''}" data-auth-mode="signup" aria-pressed="${!login}">패스 만들기</button><button class="${login?'active':''}" data-auth-mode="login" aria-pressed="${login}">로그인</button></div><h2 class="page-heading" style="margin-top:24px">${login?'다시 만나 반가워요.':'내 취향의 혜택,<br>놓치지 않도록.'}</h2><p class="auth-demo-label">${login?'로그인':'패스 만들기'} 프로토타입 체험</p><form id="signupForm"><label class="field" for="email">이메일</label><input id="email" name="email" type="email" autocomplete="off" placeholder="예: demo@example.com" required><label class="field" for="password">비밀번호</label><input id="password" type="password" autocomplete="off" minlength="8" placeholder="체험용 비밀번호 8자 이상" required><label class="check"><input type="checkbox" required><span>실제 계정 인증이 없는<br>프로토타입 체험임을 확인했어요.</span></label><p class="form-error" id="formError" role="alert"></p><button class="primary" type="submit">${login?'로그인':'패스 만들기'} ${icon('arrow')}</button></form><button class="guest" data-nav="home">가입 없이 계속 둘러보기</button><p class="notice">체험용 이메일과 비밀번호를 입력해주세요.<br>입력 정보는 서버로 전송하거나 저장하지 않습니다.<br>체험 완료 상태만 이 브라우저에 보관합니다.</p></div>`}
function completeAuthDemo(){const login=state.authMode==='login';state.joined=true;nav('profile');toast(login?'로그인 체험이 완료됐어요.':'체험용 쇼핑 패스가 만들어졌어요.')}
function profileMotion(){return `<div class="profile-motion" role="img" aria-label="광안대교를 따라 노란 빛이 흐르고 파도가 움직이는 부산 모션그래픽"><svg viewBox="0 0 346 116" fill="none" aria-hidden="true"><g class="profile-bridge-base" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"><path d="M5 80h336M65 80V30m216 50V30M5 72Q65 77 65 32q108 72 216 0 0 45 60 40M20 75v5m24-14v14m44-33v33m24-20v20m24-11v11m24-5v5m24-2v2m24-5v5m24-11v11m24-20v20m44-14v14m24 9v5"/></g><path class="profile-bridge-beam" pathLength="100" d="M5 72Q65 77 65 32q108 72 216 0 0 45 60 40" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path class="profile-deck-beam" pathLength="100" d="M5 80h336" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><g class="profile-motion-gulls" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="M218 22q5-6 10 0 5-6 10 0m19-10q4-4 8 0 4-4 8 0"/></g><g class="profile-motion-waves" stroke="currentColor" stroke-width="1.1" opacity=".3"><path class="profile-wave-back" d="M-100 96q25-7 50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0"/><path class="profile-wave-front" d="M-100 108q25-5 50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0t50 0"/></g></svg></div>`}

function profile(){return head()+`<div class="pad"><div class="profile-card"><div class="avatar">${state.joined?'B':'↘'}</div><h3>마이</h3><p class="subheading">${state.joined?'체험 회원':'게스트'}</p>${!state.joined?'<button class="primary" data-nav="signup">패스 만들기/로그인 ↗</button>':'<span class="badge-label">체험 회원 · 로컬 데모</span>'}</div><button class="menu-row" data-nav="saved">저장한 혜택 <span class="count">${state.saved.size}</span></button><button class="menu-row" data-language-next="home">언어 설정 / Language <span>${languageOptions.find(l=>l.code===state.language)?.native||'한국어'}</span></button><button class="menu-row" data-action="about">서비스 안내 ${icon('arrow')}</button>${state.joined?'<button class="menu-row" data-action="logout">체험 회원 로그아웃 ↗</button>':''}${profileMotion()}</div>`}
function detailActions(){const d=deals.find(item=>item.id===state.deal);if(!d)return '';const isProduct=d.id===7;return `<div class="detail-action-panel">${isProduct?`<div class="purchase-timer"><span>행사 종료까지</span><strong data-event-clock>${clockText()}</strong></div>`:''}<div class="purchase-buttons"><button class="secondary detail-save" data-save="${d.id}" aria-label="${state.saved.has(d.id)?'상품 저장 해제':'상품 저장'}" aria-pressed="${state.saved.has(d.id)}">${icon('heart')}</button><a class="primary detail-purchase" href="${isProduct?product.url:d.url}" target="_blank" rel="noopener noreferrer">바로 사러가기</a></div></div>`}
function render(){let view={intro,language:languagePicker,home,brands:brandList,busan,place:placePage,browse,saved,detail,signup,profile,brand:brandPage,stores:storeMap};$('#phone').className='phone '+state.screen;$('#phone').dataset.theme=state.theme;$('#phone').style.setProperty('--accent',state.theme==='wire'?'#dedede':state.color);$('#viewport').innerHTML=localizeHtml(view[state.screen]());$('#detailActions').innerHTML=state.screen==='detail'?localizeHtml(detailActions()):'';$('#phone').classList.toggle('has-purchase-timer',state.screen==='detail'&&state.deal===7);let noNav=['intro','language','signup'].includes(state.screen);$('#bottomNav').style.display=noNav?'none':'flex';$('#tripDock').innerHTML=tripDock();$('#bottomNav').innerHTML=[['home','홈','home'],['brands','브랜드','grid'],['stores','매장찾기','store'],['saved','저장','heart'],['profile','마이','user']].map(([s,l,i])=>`<button class="${(state.screen===s||(s==='brands'&&state.screen==='brand')||(s==='busan'&&state.screen==='place'))?'active':''}" data-nav="${s}" ${state.screen===s?'aria-current="page"':''}>${icon(i)}${translateText(l)}</button>`).join('');$('#screenLinks').innerHTML=Object.entries(screens).map(([s,l],i)=>`<button class="screen-link ${state.screen===s?'selected':''}" data-nav="${s}"><span>0${i+1} &nbsp; ${l}</span><span>↗</span></button>`).join('');document.querySelectorAll('[data-theme]').forEach(b=>{if(b.tagName==='BUTTON')b.classList.toggle('selected',b.dataset.theme===state.theme)});$('#colorLabel').textContent=`${state.color.toUpperCase()} ${state.theme==='wire'?'· 와이어프레임 적용 중':''}`;let sp=state.screen==='detail'&&state.deal===7?['니베아 상품 상세','공식 가격과 행사 일정을 확인하고 상품 구매 페이지로 이동합니다.',['상품 이미지|고해상도 연출 썸네일|원본 제품을 기울여 앰버 배경에 배치','가격 비교|22,500원 → 12,500원부터|44% 할인 · 10,000원 절약','행사 기간|2026.11.01 – 11.07 · 한국 시간|행사 종료 카운트다운 / 종료 후 상태 변경','구매 CTA|하단 고정 버튼|올리브영 해당 상품을 새 탭에서 열기']]:specs[state.screen];$('#specTitle').textContent=sp[0];$('#specCopy').textContent=sp[1];$('#specs').innerHTML=sp[2].map(x=>{let[a,b,c]=x.split('|');return `<div class="spec"><b>${a}</b><span>${b}</span><span>${c}</span></div>`}).join('');$('#screenLabel').textContent=state.screen.toUpperCase();persist();bindView();maybeShowTripPrompt()}
specs.language=['언어 선택','인트로 다음에 사용할 언어를 고르고 서비스에 진입합니다.',['지원 언어|한국어 · 日本語 · 中文 · English|기본 메뉴와 버튼 언어 적용','선택 유지|기기 브라우저에 저장|마이에서 다시 변경']];
specs.stores=['부산 매장 찾기','무채색 전체 화면 지도에서 포인트 컬러 핀으로 매장을 찾습니다.',['지도 탐색|1–4배 확대 · 축소|버튼 · 휠 · 두 손가락 · 드래그 이동','매장 핀|브랜드별 6개 시연 매장|선택한 핀 확대 모션, 지도 배율 유지','매장 정보|선택 시 하단 요약|위치와 운영 정보는 시연용']];
let bannerRotationSince=Date.now();
let bannerTransitioning=false;
let historyStack=[];function nav(s,options={}){if(s==='stores')state.mapShowBack=!!options.showBack;if(s==='stores'&&state.screen!=='stores'){mapEntryAt=Date.now();resetMapCamera();state.store=null}if(s==='home')restartBannerRotation();if(s!==state.screen)historyStack.push(state.screen);state.screen=s;state.filter='전체';state.query='';$('#modal').innerHTML='';render();$('#viewport').scrollTop=0}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function sheet(title,copy,footer){$('#modal').innerHTML=localizeHtml(`<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><h3>${title}</h3><p>${copy}</p>${footer||''}<button class="secondary" data-action="close">닫기</button></section></div>`);$('#modal').querySelector('a,button')?.focus()}function external(i){let b=brands[i];sheet(`${b.name} 공식몰로 이동`,`${b.desc}<br>실제 행사·기간·가격은 공식몰에서 확인해주세요.<br>새 탭에서 열리며 저장한 혜택은 유지됩니다.`,`<a class="primary" href="${b.url}" target="_blank" rel="noopener noreferrer">공식몰 열기 ↗</a>`)}
document.addEventListener('click',async e=>{let b=e.target.closest('button,a[data-nav],[data-deal]');if(!b)return;if(b.dataset.theme){state.theme=b.dataset.theme;render()}else if(b.dataset.authMode){state.authMode=b.dataset.authMode==='login'?'login':'signup';render()}else if(b.dataset.tripEdit){openTripSettings()}else if(b.dataset.tripClear){$('#modal').innerHTML='';state.visitStart='';state.visitEnd='';state.banner=0;render()}else if(b.dataset.languageChoice){state.pendingLanguage=b.dataset.languageChoice;render()}else if(b.dataset.languageEnter){state.language=state.pendingLanguage;state.languageReady=true;nav(state.languageNext||'home');state.languageNext=null}else if(b.dataset.languageNext){state.languageNext=b.dataset.languageNext;nav('language')}else if(b.dataset.nav){nav(b.dataset.nav)}else if(b.dataset.deal){state.deal=Number(b.dataset.deal);nav('detail')}else if(b.dataset.localFilter){state.localFilter=b.dataset.localFilter;render()}else if(b.dataset.area){state.area=b.dataset.area;render()}else if(b.dataset.place){state.place=b.dataset.place;nav('place')}else if(b.dataset.stores!==undefined){state.brand=Number(b.dataset.stores);state.mapLocal=false;state.store=null;resetMapCamera();nav('stores',{showBack:true})}else if(b.dataset.mapRegion){selectMapRegion(b.dataset.mapRegion)}else if(b.dataset.storeSave!==undefined){toggleStoreSave(Number(b.dataset.storeSave))}else if(b.dataset.savedStoresOnly!==undefined){state.savedStoresOnly=!state.savedStoresOnly;state.store=null;render()}else if(b.dataset.mapDismiss){state.store=null;render()}else if(b.dataset.store!==undefined){state.store=Number(b.dataset.store);render()}else if(b.dataset.mapLocal){state.mapLocal=true;state.store=null;render()}else if(b.dataset.mapBrand!==undefined){state.mapLocal=false;state.brand=Number(b.dataset.mapBrand);state.store=state.savedStoresOnly?null:0;render()}else if(b.dataset.brand!==undefined){state.brand=Number(b.dataset.brand);nav('brand')}else if(b.dataset.save){let y=$('#viewport').scrollTop,id=Number(b.dataset.save),adding=!state.saved.has(id);adding?state.saved.add(id):state.saved.delete(id);render();$('#viewport').scrollTop=y;toast(adding?'저장했어요. 저장함에서 다시 만나요.':'저장을 해제했어요.')}else if(b.dataset.filter){const categoryStrip=$('.product-category-chips'),offset=categoryStrip?.scrollLeft||0;state.filter=b.dataset.filter;let y=$('#viewport').scrollTop;render();$('#viewport').scrollTop=y;const nextStrip=$('.product-category-chips');if(nextStrip)nextStrip.scrollLeft=offset}else if(b.dataset.banner!==undefined){switchCampaign(Number(b.dataset.banner))}else if(b.dataset.out!==undefined){external(Number(b.dataset.out))}else if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('시연용 쿠폰 코드를 복사했어요.')}catch{sheet('시연용 쿠폰 코드',b.dataset.copy+'<br>길게 눌러 직접 복사해주세요.')}}else if(b.dataset.action){switch(b.dataset.action){case'back':state.screen=historyStack.pop()||'home';if(state.screen==='stores'){mapEntryAt=Date.now();resetMapCamera();state.store=null}render();$('#viewport').scrollTop=0;break;case'close':$('#modal').innerHTML='';break;case'about':sheet('부산 가기 전, BUSAN DROP','국내 쇼핑몰의 할인 정보를 둘러보고 저장하는 부산 여행 전 쇼핑 큐레이션입니다.<br>전국 브랜드 세일과 부산 로컬·팝업 정보를 공식 출처로 확인해 제공합니다. 미확정 일정은 구분해 표시합니다.<br><br>본 서비스는 부산을 찾는 관광객의 여행과 쇼핑 편의를 위해 정보를 제공하며, 영리 목적으로 운영하지 않습니다.');break;case'logout':state.joined=false;render();toast('체험 회원에서 로그아웃했어요.');break}}});
function bindTripForm(form){if(!form)return;form.querySelectorAll('input[name="shoppingType"]').forEach(input=>input.addEventListener('change',()=>{const all=form.querySelector('input[value="전체"]'),choices=[...form.querySelectorAll('input[name="shoppingType"]')].filter(el=>el.value!=='전체');if(input===all)choices.forEach(el=>el.checked=all.checked);else all.checked=choices.every(el=>el.checked)}));form.addEventListener('submit',e=>{e.preventDefault();const form=e.target,start=form.elements.visitStart.value,end=form.elements.visitEnd.value;if((start||end)&&(!validVisitDate(start)||!validVisitDate(end)||end<start)){$('#tripError').textContent='도착일과 마지막 날을 확인해주세요. 마지막 날은 도착일 이후여야 해요.';return}const selectedTypes=[...form.querySelectorAll('input[name="shoppingType"]:checked')].map(el=>el.value).filter(t=>t!=='전체');if(!selectedTypes.length){$('#tripError').textContent='쇼핑 타입을 하나 이상 선택해주세요.';return}state.tripConfigured=true;state.visitStart=start;state.visitEnd=end;state.shoppingTypes=selectedTypes;state.banner=0;persist();if(form.dataset.onboarding==='true')nav('language');else{$('#modal').innerHTML='';render();toast('내 일정과 취향을 적용했어요.')}})}
function bindView(){bindStoreMap();bindCategorySwipe();bindTripForm($('#tripForm'));let input=$('#search');if(input)input.addEventListener('input',()=>{state.query=input.value;if(state.screen==='brands')$('#brandResults').innerHTML=brandRows();else{$('#results').innerHTML=filtered().map(card).join('')||empty('검색 결과가 없어요','검색어나 카테고리를 바꿔보세요.');$('#resultCount').textContent=filtered().length+'개의 혜택'}});$('#sort')?.addEventListener('change',e=>{state.sort=e.target.value;$('#results').innerHTML=filtered().map(card).join('')});$('#signupForm')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;$('#password').value='';$('#email').value='';completeAuthDemo()});let hero=$('#hero'),startX=0;hero?.addEventListener('touchstart',e=>startX=e.changedTouches[0].clientX,{passive:true});hero?.addEventListener('touchend',e=>{let delta=e.changedTouches[0].clientX-startX;if(Math.abs(delta)>45){switchCampaign((state.banner+(delta<0?1:banners.length-1))%banners.length,delta<0?1:-1)}},{passive:true})}
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal').innerHTML='';if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-deal]')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&$('#modal .sheet')){let f=[...$('#modal').querySelectorAll('button,a,input')],first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('#reset').onclick=()=>{historyStack=[];state.tripPromptSeen=false;state.languageNext=null;nav('intro')};render();

setInterval(()=>{document.querySelectorAll('[data-event-clock]').forEach(el=>el.textContent=clockText());document.querySelectorAll('[data-event-status]').forEach(el=>el.textContent=eventStatus());document.querySelectorAll('[data-buy-label]').forEach(el=>el.textContent=eventStatus()==='종료'?'행사 종료 · 현재가 확인':'행사 끝나기 전에')},1000);

setInterval(()=>document.querySelectorAll("[data-sale-timer]").forEach(el=>el.textContent=visitLabel(brands[Number(el.dataset.saleTimer)])),30000);

function restartBannerRotation(){bannerRotationSince=Date.now()}
setInterval(()=>{
  if(state.screen!=='home'||document.hidden||document.querySelector('#modal .sheet')){restartBannerRotation();return}
  if(Date.now()-bannerRotationSince<9000)return;
  switchCampaign((state.banner+1)%banners.length,1);
},500);

async function switchCampaign(next,direction){
  restartBannerRotation();
  if(bannerTransitioning||next===state.banner||!Number.isInteger(next)||next<0||next>=banners.length)return;
  const old=document.querySelector('#hero');
  const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  const canAnimate=state.screen==='home'&&old?.animate&&!reduced;
  const outgoing=canAnimate?old.cloneNode(true):null;
  const sign=direction??(next>state.banner?1:-1);
  state.banner=next;render();
  if(!outgoing)return;
  const incoming=document.querySelector('#hero'),stage=document.querySelector('.campaign-stage');
  if(!incoming||!stage)return;
  bannerTransitioning=true;
  outgoing.removeAttribute('id');outgoing.setAttribute('aria-hidden','true');outgoing.inert=true;
  outgoing.classList.add('campaign-outgoing');stage.append(outgoing);
  const timing={duration:560,easing:'cubic-bezier(.22,.7,.18,1)',fill:'both'};
  const out=outgoing.animate([{transform:'translateX(0) scale(1)',filter:'blur(0px)',opacity:1},{transform:`translateX(${-sign*48}%) scale(1.035)`,filter:'blur(12px)',opacity:0}],timing);
  const enter=incoming.animate([{transform:`translateX(${sign*48}%) scale(1.035)`,filter:'blur(12px)',opacity:0},{transform:'translateX(0) scale(1)',filter:'blur(0px)',opacity:1}],timing);
  try{await Promise.all([out.finished,enter.finished])}catch{}finally{outgoing.remove();out.cancel();enter.cancel();bannerTransitioning=false}
}


function bindCategorySwipe(){
 const strip=$('.product-category-chips');if(!strip)return;
 let dragging=false,startX=0,startScroll=0,moved=false,pointerId=null;
 const update=()=>{const box=strip.getBoundingClientRect(),canLeft=strip.scrollLeft>2,canRight=strip.scrollLeft+strip.clientWidth<strip.scrollWidth-2;strip.classList.toggle('can-swipe-left',canLeft);strip.classList.toggle('can-swipe-right',canRight);strip.querySelectorAll('.chip').forEach(chip=>{const r=chip.getBoundingClientRect();chip.classList.toggle('swipe-edge-blur',(canLeft&&r.left<box.left+22)||(canRight&&r.right>box.right-22))})};
 strip.addEventListener('scroll',update,{passive:true});
 strip.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;dragging=true;moved=false;pointerId=e.pointerId;startX=e.clientX;startScroll=strip.scrollLeft});
 strip.addEventListener('pointermove',e=>{if(!dragging||e.pointerId!==pointerId)return;const delta=e.clientX-startX;if(!moved&&Math.abs(delta)>6){moved=true;strip.setPointerCapture(e.pointerId);strip.classList.add('dragging')}if(moved){e.preventDefault();strip.scrollLeft=startScroll-delta}});
 const finish=e=>{if(e.pointerId!==pointerId)return;dragging=false;strip.classList.remove('dragging');if(strip.hasPointerCapture(e.pointerId))strip.releasePointerCapture(e.pointerId);if(!moved)pointerId=null;update()};
 strip.addEventListener('pointerup',finish);strip.addEventListener('pointercancel',finish);
 strip.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;pointerId=null}},true);
 strip.addEventListener('dragstart',e=>e.preventDefault());
 strip.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();strip.scrollBy({left:e.key==='ArrowRight'?144:-144,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}});
 strip.setAttribute('tabindex','0');strip.setAttribute('aria-description','좌우로 스와이프하거나 마우스로 드래그해 카테고리를 더 볼 수 있습니다. 방향키도 사용할 수 있습니다.');
 if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(()=>{if(!strip.isConnected){observer.disconnect();return}update()});observer.observe(strip)}
 update();
}
